typedef unsigned long size_t;
typedef struct _IO_FILE FILE; extern FILE *stdout; int setbuf(FILE*,char*);
void *malloc(size_t); void free(void*);
int printf(const char*,...);
int main(void){
  setbuf(stdout,0);
  char *A=malloc(0x50), *B=malloc(0x50), *C=malloc(0x50);
  printf("A=%p size=0x%lx\n",(void*)A,((unsigned long*)A)[-1]);
  printf("B=%p size=0x%lx\n",(void*)B,((unsigned long*)B)[-1]);
  printf("C=%p size=0x%lx\n",(void*)C,((unsigned long*)C)[-1]);
  ((unsigned char*)A)[-8]=0xe1;                 /* off-by-one: 0x61 -> 0xe1 */
  printf("corrupted A.size -> 0x%lx  (covers A and B)\n",((unsigned long*)A)[-1]);
  free(A);
  char *D=(char*)malloc(0xd0);
  printf("D = malloc(0xd0) = %p  (== A? %s)\n",D, D==A?"yes":"no");
  for(int i=0;i<16;i++) B[i]=(char)0x42;
  printf("wrote 'B' bytes to B[0..15]:  D[0x60..0x6f] now = ");
  for(int i=0;i<4;i++) printf("%02x ",(unsigned char)D[0x60+i]);
  printf("\n");
  return 0;
}
